// ─── Event Allowance Logic ────────────────────────────────────────────────────

const EVENT_ALLOWANCE_TYPE = "Event Allowance";
const SUBSISTENCE_ALLOWANCE_KEY = "Subsistence";
const CHILD_DOCTYPE = "Event Allowance Employee Table";  // ← CORRECTED

// ─── Toggle table visibility based on advance type ──────────────────────

function toggle_event_allowance_table(frm) {
    if (frm.doc.docstatus === 1) return;

    const is_event_allowance = frm.doc.custom_advance_options === EVENT_ALLOWANCE_TYPE;
    const was_event_allowance = frm._previous_advance_type === EVENT_ALLOWANCE_TYPE;

    frm.toggle_display("custom_participants_table", is_event_allowance);

    // Only clear advance_amount if SWITCHING FROM Event Allowance TO something else
    if (was_event_allowance && !is_event_allowance) {
        frm.clear_table("custom_participants_table");
        frm.set_value("advance_amount", 0);
    } else if (is_event_allowance) {
        // When switching TO Event Allowance, auto-calculate total
        auto_calculate_total_allowance(frm);
    }

    // Remember current type for next toggle
    frm._previous_advance_type = frm.doc.custom_advance_options;
}

// ─── Auto-calculate total allowance from all participants ────────────────────

function auto_calculate_total_allowance(frm) {
    if (frm.doc.docstatus === 1) return;

    if (frm.doc.custom_advance_options !== EVENT_ALLOWANCE_TYPE) return;

    const participants = frm.doc.custom_participants_table || [];

    // Sum all allowance values
    const total = participants.reduce((sum, row) => {
        return sum + (parseFloat(row.allowance) || 0);
    }, 0);

    // Set advance amount to total
    frm.set_value("advance_amount", total);

    // Log for debugging
    console.log(`Total Event Allowance: ZMW ${total.toFixed(2)}`);
}

// ─── Fetch subsistence allowance from Employee Grade ────────────────────────

function fetch_subsistence_allowance(employee, callback) {
    console.log(`[Event Allowance] Fetching grade for employee: ${employee}`);

    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Employee",
            name: employee,
            fields: ["grade", "name", "employee_name"]
        },
        callback: (r) => {
            if (r.message) {
                const grade = r.message.grade;
                console.log(`[Event Allowance] Employee ${employee} has grade: ${grade}`);

                if (!grade) {
                    frappe.msgprint({
                        title: "Grade Not Found",
                        message: `Employee <b>${employee}</b> (${r.message.employee_name}) has no grade assigned.`,
                        indicator: "orange"
                    });
                    console.warn(`[Event Allowance] No grade found for ${employee}`);
                    callback(null);
                    return;
                }

                // Fetch Employee Grade and its allowances
                frappe.call({
                    method: "frappe.client.get",
                    args: {
                        doctype: "Employee Grade",
                        name: grade,
                        fields: ["custom_non_taxable_allowances"]
                    },
                    callback: (grade_r) => {
                        if (grade_r.message) {
                            console.log(`[Event Allowance] Grade ${grade} data:`, grade_r.message);

                            const allowances = grade_r.message.custom_non_taxable_allowances || [];
                            console.log(`[Event Allowance] Allowances in grade: ${allowances.length} rows`);

                            // Find Subsistence Allowance
                            const subsistence = allowances.find(
                                (a) => a.allowance_type === SUBSISTENCE_ALLOWANCE_KEY
                            );

                            if (subsistence) {
                                console.log(`[Event Allowance] Found Subsistence:`, subsistence);

                                // Convert to number (handles currency field)
                                let amount = subsistence.amount;
                                if (typeof amount === 'string') {
                                    amount = parseFloat(amount.replace(/[^\d.-]/g, ''));
                                } else {
                                    amount = parseFloat(amount) || 0;
                                }

                                console.log(`[Event Allowance] Subsistence amount (converted): ${amount}`);

                                if (isNaN(amount) || amount <= 0) {
                                    frappe.msgprint({
                                        title: "Invalid Amount",
                                        message: `Subsistence allowance in Grade <b>${grade}</b> has an invalid amount: <b>${subsistence.amount}</b>`,
                                        indicator: "orange"
                                    });
                                    callback(null);
                                } else {
                                    callback(amount);
                                }
                            } else {
                                console.warn(`[Event Allowance] Subsistence not found. Available types:`, 
                                    allowances.map(a => a.allowance_type).join(', '));

                                frappe.msgprint({
                                    title: "Allowance Not Found",
                                    message: `<b>Subsistence</b> allowance not configured in Grade <b>${grade}</b>.<br>Available types: ${allowances.map(a => a.allowance_type).join(', ')}`,
                                    indicator: "orange"
                                });
                                callback(null);
                            }
                        } else {
                            console.error(`[Event Allowance] Failed to fetch grade data`);
                            callback(null);
                        }
                    },
                    error: (err) => {
                        console.error(`[Event Allowance] Error fetching grade:`, err);
                        frappe.msgprint({
                            title: "Error",
                            message: `Failed to fetch grade data. Check browser console (F12) for details.`,
                            indicator: "red"
                        });
                        callback(null);
                    }
                });
            } else {
                console.error(`[Event Allowance] Employee not found: ${employee}`);
                callback(null);
            }
        },
        error: (err) => {
            console.error(`[Event Allowance] Error fetching employee:`, err);
            frappe.msgprint({
                title: "Error",
                message: `Failed to fetch employee data. Check browser console (F12) for details.`,
                indicator: "red"
            });
            callback(null);
        }
    });
}

// ─── Auto-populate allowance when employee is selected ──────────────────────

function auto_populate_allowance(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    if (!row.employee) {
        frappe.msgprint("Please select an employee first.");
        return;
    }

    // Show loading indicator
    frappe.show_progress("Fetching Allowance", 50);

    fetch_subsistence_allowance(row.employee, (amount) => {
        frappe.hide_progress();

        if (amount !== null && amount > 0) {
            // Show half of the subsistence allowance
            const half_amount = amount / 2;
            console.log(`[Event Allowance] Setting allowance to: ${half_amount}`);

            frappe.model.set_value(cdt, cdn, "allowance", half_amount);
            frm.refresh_field("custom_participants_table");

            // Auto-calculate total after allowance is populated
            setTimeout(() => {
                auto_calculate_total_allowance(frm);
            }, 100);
        } else {
            console.warn(`[Event Allowance] Invalid amount returned: ${amount}`);
        }
    });
}

// ─── Event Bindings ──────────────────────────────────────────────────────────

frappe.ui.form.on("Employee Advance", {

    refresh(frm) {
        toggle_event_allowance_table(frm);
        auto_calculate_total_allowance(frm);
    },

    custom_advance_options(frm) {
        if (frm.doc.docstatus === 1) return;
        toggle_event_allowance_table(frm);
    }

});

// ─── Child Table Events - USES CORRECT DOCTYPE NAME ──────────────────────────

frappe.ui.form.on(CHILD_DOCTYPE, {

    employee(frm, cdt, cdn) {
        console.log(`[Event Allowance] Employee field triggered on ${CHILD_DOCTYPE}`);
        auto_populate_allowance(frm, cdt, cdn);
    },

    allowance(frm) {
        // When allowance is manually changed, recalculate total
        auto_calculate_total_allowance(frm);
    },

    custom_participants_table_add(frm) {
        // When a row is added, recalculate total
        auto_calculate_total_allowance(frm);
    },

    custom_participants_table_remove(frm) {
        // When a row is removed, recalculate total
        auto_calculate_total_allowance(frm);
    }

});

frappe.ui.form.on('Employee Advance', {

    before_save: async function(frm) {

        if (!frm.doc.employee) {
            frappe.throw("Please select an Employee");
        }

        let total_earnings = 0;
        let total_structural_deductions = 0;
        let total_additional_deductions = 0;
        let total_loan_deductions = 0;
        let base_salary = 0;

        let earnings_rows = "";
        let structural_rows = "";
        let additional_rows = "";
        let loan_rows = "";

        // 1. Salary Structure Assignment
        let assignment = await frappe.db.get_list("Salary Structure Assignment", {
            filters: { employee: frm.doc.employee, docstatus: 1 },
            fields: ["salary_structure", "base"],
            order_by: "from_date desc",
            limit: 1
        });

        if (!assignment.length) {
            frappe.throw("No active Salary Structure Assignment found for " + frm.doc.employee);
            return;
        }

        let salary_structure = assignment[0].salary_structure;
        base_salary = flt(assignment[0].base || 0);

        // 2. Fetch employee grade (needed for formulas like Housing Allowance)
        let emp_data = await frappe.db.get_value("Employee", frm.doc.employee, "grade");
        let grade = (emp_data && emp_data.message && emp_data.message.grade) ? emp_data.message.grade : "";

        // 3. Salary Structure
        let structure = await frappe.db.get_doc("Salary Structure", salary_structure);

        // ── FIRST PASS: Compute Earnings to get gross_pay ───────────

        total_earnings = total_earnings + base_salary;
        earnings_rows = earnings_rows + "<tr><td><b>Basic Salary</b></td><td align='right'><b>"
            + format_currency(base_salary) + "</b></td><td>Base</td></tr>";

        for (let row of structure.earnings) {
            if (row.salary_component && row.salary_component.toLowerCase().includes("basic")) continue;
            let amount = 0;
            if (!row.amount_based_on_formula) {
                amount = flt(row.amount || 0);
            } else if (row.formula) {
                amount = computeFormula(row.formula, { base: base_salary, grade: grade });
            }
            total_earnings = total_earnings + amount;
            earnings_rows = earnings_rows + "<tr><td>" + row.salary_component
                + "</td><td align='right'>" + format_currency(amount)
                + "</td><td>" + (row.formula || "Fixed") + "</td></tr>";
        }

        let gross_pay = total_earnings;

        // ── SECOND PASS: Compute Deductions (now gross_pay is known) ──
        //    Skip PAYE from structure (always 0), compute it from Income Tax Slab
        //    Track NAPSA-EE to calculate taxable income

        let napsa_ee = 0;

        for (let row of structure.deductions) {
            // Skip PAYE — we compute it separately from tax slabs
            if (row.salary_component && row.salary_component.toUpperCase().includes("PAYE")) continue;

            let amount = 0;
            if (!row.amount_based_on_formula) {
                amount = flt(row.amount || 0);
            } else if (row.formula) {
                amount = computeFormula(row.formula, {
                    base: base_salary,
                    gross_pay: gross_pay,
                    grade: grade
                });
            }

            // Track NAPSA-EE for taxable income calculation
            if (row.salary_component && row.salary_component.toUpperCase().includes("NAPSA")
                && row.salary_component.toUpperCase().includes("EE")) {
                napsa_ee = amount;
            }

            total_structural_deductions = total_structural_deductions + amount;
            structural_rows = structural_rows + "<tr><td>" + row.salary_component
                + "</td><td align='right'>" + format_currency(amount)
                + "</td><td>" + (row.formula || "Fixed") + "</td></tr>";
        }

        // ── Compute PAYE from Income Tax Slab ───────────────────────
        let taxable_income = gross_pay - napsa_ee;
        let paye = 0;

        try {
            let tax_slab = await frappe.db.get_doc("Income Tax Slab", "PAYE");
            if (tax_slab && tax_slab.slabs) {
                for (let slab of tax_slab.slabs) {
                    let from_amt = flt(slab.from_amount || 0);
                    let to_amt = flt(slab.to_amount || 0);
                    let rate = flt(slab.percent_deduction || 0) / 100;

                    if (taxable_income <= from_amt) break;

                    let taxable_in_slab = 0;
                    if (to_amt && taxable_income > to_amt) {
                        taxable_in_slab = to_amt - from_amt;
                    } else {
                        taxable_in_slab = taxable_income - from_amt;
                    }

                    paye = paye + (taxable_in_slab * rate);
                }
            }
        } catch (e) {
            console.log("PAYE computation error:", e);
        }

        paye = flt(paye);
        total_structural_deductions = total_structural_deductions + paye;
        structural_rows = "<tr><td>PAYE</td><td align='right'>" + format_currency(paye)
            + "</td><td>Taxable: " + format_currency(taxable_income) + " (Gross - NAPSA-EE)</td></tr>"
            + structural_rows;

        // 4. Additional Salary Deductions (current posting month only)
        let posting_date = frm.doc.posting_date || frappe.datetime.get_today();
        let month_start = posting_date.substring(0, 7) + "-01";
        let ms_year = parseInt(posting_date.substring(0, 4));
        let ms_month = parseInt(posting_date.substring(5, 7));
        let month_end = new Date(ms_year, ms_month, 0).toISOString().substring(0, 10);

        let additional_salaries = await frappe.db.get_list("Additional Salary", {
            filters: {
                employee: frm.doc.employee,
                docstatus: 1,
                payroll_date: ["between", [month_start, month_end]]
            },
            fields: ["name", "salary_component", "amount", "payroll_date"],
            order_by: "payroll_date asc",
            limit: 100
        });

        for (let record of additional_salaries) {
            let comp_type = await frappe.db.get_value("Salary Component", record.salary_component, "type");
            if (comp_type && comp_type.message && comp_type.message.type === "Deduction") {
                let amount = flt(record.amount || 0);
                total_additional_deductions = total_additional_deductions + amount;
                additional_rows = additional_rows + "<tr><td>" + record.salary_component
                    + "</td><td align='right'>" + format_currency(amount)
                    + "</td><td>" + record.payroll_date + "</td></tr>";
            }
        }

        // 5. Loan Repayments
        let loans = await frappe.db.get_list("Loan", {
            filters: {
                applicant: frm.doc.employee,
                docstatus: 1,
                status: ["in", ["Disbursed", "Partially Paid"]]
            },
            fields: ["name", "loan_amount", "total_payment", "repayment_periods", "monthly_repayment_amount", "total_amount_paid"],
            limit: 100
        });

        for (let loan of loans) {
            let remaining = flt(loan.total_payment) - flt(loan.total_amount_paid);
            if (remaining <= 0) continue;
            let monthly = flt(loan.monthly_repayment_amount || 0);
            if (!monthly && loan.repayment_periods > 0) {
                monthly = remaining / loan.repayment_periods;
            }
            total_loan_deductions = total_loan_deductions + monthly;
            loan_rows = loan_rows + "<tr><td>" + loan.name
                + "</td><td align='right'>" + format_currency(monthly)
                + "</td><td>Remaining: " + format_currency(remaining) + "</td></tr>";
        }

        // Totals
        let total_all_deductions = total_structural_deductions + total_additional_deductions + total_loan_deductions;
        let net = total_earnings - total_all_deductions;

        // 40% Debt Ratio Validation
        let validation_msg = "";
        let can_approve = true;

        if (frm.doc.advance_amount && frm.doc.custom_deduction_duration) {
            let advance_amount = flt(frm.doc.advance_amount || 0);
            let months = parseInt(frm.doc.custom_deduction_duration);

            if (months && advance_amount > 0) {
                let monthly_deduction = advance_amount / months;
                let minimum_takehome = total_earnings * 0.40;
                let projected_takehome = net - monthly_deduction;
                let max_allowed_monthly = net - minimum_takehome;
                let max_allowed_total = max_allowed_monthly * months;

                if (projected_takehome < minimum_takehome) {
                    can_approve = false;
                    validation_msg = "<br><b>ADVANCE NOT ELIGIBLE</b><br>"
                        + "Projected take-home (" + format_currency(projected_takehome)
                        + ") falls below the minimum 40% threshold (" + format_currency(minimum_takehome) + ").<br>"
                        + "Maximum advance allowed: " + format_currency(Math.max(0, max_allowed_total))
                        + " over " + months + " month(s).<br>"
                        + "Reduce the amount or extend the repayment period.";
                } else {
                    let buffer = projected_takehome - minimum_takehome;
                    validation_msg = "<br><b>ADVANCE ELIGIBLE</b><br>"
                        + "Projected take-home: " + format_currency(projected_takehome)
                        + " | Minimum required (40%): " + format_currency(minimum_takehome)
                        + " | Buffer: " + format_currency(buffer);
                }
            }
        }

        // Build HTML
        let tbl = "style='width:100%;border-collapse:collapse;margin-bottom:10px;'";
        let th = "style='padding:4px;border-bottom:2px solid #999;text-align:left;'";
        let thr = "style='padding:4px;border-bottom:2px solid #999;text-align:right;'";
        let td_total = "style='padding:4px;border-top:1px solid #999;font-weight:bold;'";

        let html = "<b>Employee:</b> " + (frm.doc.employee_name || frm.doc.employee)
            + " | <b>Structure:</b> " + salary_structure
            + " | <b>Grade:</b> " + (grade || "N/A")
            + " | <b>Period from:</b> " + month_start

            + "<br><br><b>Earnings</b>"
            + "<table " + tbl + "><tr><th " + th + ">Component</th><th " + thr + ">Amount</th><th " + th + ">Source</th></tr>"
            + earnings_rows
            + "<tr><td " + td_total + ">TOTAL</td><td " + td_total + " align='right'>" + format_currency(total_earnings) + "</td><td></td></tr></table>"

            + "<b>Structural Deductions</b>"
            + "<table " + tbl + "><tr><th " + th + ">Component</th><th " + thr + ">Amount</th><th " + th + ">Source</th></tr>"
            + (structural_rows || "<tr><td colspan='3'>None</td></tr>")
            + "<tr><td " + td_total + ">SUBTOTAL</td><td " + td_total + " align='right'>" + format_currency(total_structural_deductions) + "</td><td></td></tr></table>"

            + "<b>Additional Salary Deductions (" + month_start + " to " + month_end + ")</b>"
            + "<table " + tbl + "><tr><th " + th + ">Component</th><th " + thr + ">Amount</th><th " + th + ">Payroll Date</th></tr>"
            + (additional_rows || "<tr><td colspan='3'>None</td></tr>")
            + "<tr><td " + td_total + ">SUBTOTAL</td><td " + td_total + " align='right'>" + format_currency(total_additional_deductions) + "</td><td></td></tr></table>"

            + "<b>Loan Repayments</b>"
            + "<table " + tbl + "><tr><th " + th + ">Loan</th><th " + thr + ">Monthly</th><th " + th + ">Remaining</th></tr>"
            + (loan_rows || "<tr><td colspan='3'>None</td></tr>")
            + "<tr><td " + td_total + ">SUBTOTAL</td><td " + td_total + " align='right'>" + format_currency(total_loan_deductions) + "</td><td></td></tr></table>"

            + "<hr>"
            + "<b>Gross:</b> " + format_currency(total_earnings)
            + " | <b>Total Deductions:</b> " + format_currency(total_all_deductions)
            + " | <b>Net:</b> " + format_currency(net)

            + (frm.doc.advance_amount ? "<br><b>Advance:</b> " + format_currency(flt(frm.doc.advance_amount))
                + " over " + (parseInt(frm.doc.custom_deduction_duration) || "?") + " month(s)"
                + " = " + format_currency(flt(frm.doc.advance_amount) / (parseInt(frm.doc.custom_deduction_duration) || 1)) + "/month"
                : "")

            + "<br>" + validation_msg;

        if (!can_approve) {
            frappe.throw({ title: "Advance Not Eligible - Debt Ratio Exceeded", message: html });
        } else if (validation_msg) {
            frappe.msgprint({ title: "Advance Eligible", message: html, indicator: "green" });
        }
    }
});


// ─── Formula Helper ──────────────────────────────────────────────────────────
// Converts Python-style salary structure formulas to JS and evaluates them.

function computeFormula(formula, variables) {
    try {
        let f = formula;

        // Step 1: Substitute variables FIRST (before syntax conversion)
        // so that string comparisons work correctly in JS
        for (let key in variables) {
            let val = variables[key];
            let replacement = (typeof val === "string") ? '"' + val + '"' : String(val);
            f = f.replace(new RegExp('\\b' + key + '\\b', 'g'), replacement);
        }

        // Step 2: Convert Python 'in [list]' to JS
        // e.g. "REA 4" in ["REA 1","REA 2"] → ["REA 1","REA 2"].includes("REA 4")
        f = f.replace(/"([^"]+)"\s+in\s+(\[.*?\])/g, '$2.includes("$1")');

        // Step 3: Convert Python ternary to JS ternary
        f = convertTernary(f);

        let result = eval(f);
        return flt(result || 0);

    } catch (e) {
        console.log("Formula evaluation failed:", formula, "→", e);
        return 0;
    }
}

function convertTernary(expr) {
    // Match innermost: VALUE if CONDITION else REST
    // Using lazy match on value and condition to handle nesting
    let match = expr.match(/^(.*?)\s+if\s+(.*?)\s+else\s+(.*)$/);
    if (!match) return expr;

    let value = match[1].trim();
    let condition = match[2].trim();
    let rest = match[3].trim();

    // Recursively convert nested ternaries in the else branch
    rest = convertTernary(rest);

    return '(' + condition + ') ? (' + value + ') : (' + rest + ')';
}

frappe.ui.form.on('Customer', {
	refresh(frm) {
		if (frm.doc.customer_tier) {
			const color = {Gold: 'yellow', Silver: 'gray', Bronze: 'orange'}[frm.doc.customer_tier];
			frm.page.set_indicator(__('{0} customer', [frm.doc.customer_tier]), color);
		}
	},
});
